CREATE TABLE IF NOT EXISTS stores(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,address VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,name VARCHAR(120) NOT NULL,phone VARCHAR(20) NOT NULL,role ENUM('customer','manager') NOT NULL,store_id INT NULL,FOREIGN KEY(store_id) REFERENCES stores(id));
CREATE TABLE IF NOT EXISTS sessions(token CHAR(64) PRIMARY KEY,user_id INT NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS categories(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS brands(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INT PRIMARY KEY AUTO_INCREMENT,sku VARCHAR(40) UNIQUE NOT NULL,name VARCHAR(200) NOT NULL,category_id INT NOT NULL,brand_id INT NOT NULL,price DECIMAL(14,0) NOT NULL,image VARCHAR(100) NOT NULL,specs TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT 1,FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(brand_id) REFERENCES brands(id));
CREATE TABLE IF NOT EXISTS inventory(store_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL,minimum INT NOT NULL DEFAULT 5,PRIMARY KEY(store_id,product_id),FOREIGN KEY(store_id) REFERENCES stores(id),FOREIGN KEY(product_id) REFERENCES products(id),CHECK(quantity>=0));
CREATE TABLE IF NOT EXISTS staff(id INT PRIMARY KEY AUTO_INCREMENT,store_id INT NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL,phone VARCHAR(20) NOT NULL,position VARCHAR(80) NOT NULL,active BOOLEAN NOT NULL DEFAULT 1,commission_rate DECIMAL(5,2) NOT NULL DEFAULT 1,FOREIGN KEY(store_id) REFERENCES stores(id));
CREATE TABLE IF NOT EXISTS promotions(id INT PRIMARY KEY AUTO_INCREMENT,store_id INT NULL,code VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,percent INT NOT NULL,min_total DECIMAL(14,0) NOT NULL DEFAULT 0,max_discount DECIMAL(14,0) NOT NULL,starts_at DATE NOT NULL,ends_at DATE NOT NULL,active BOOLEAN NOT NULL DEFAULT 1,FOREIGN KEY(store_id) REFERENCES stores(id));
CREATE TABLE IF NOT EXISTS orders(id INT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(40) NOT NULL UNIQUE,user_id INT NOT NULL,store_id INT NOT NULL,staff_id INT NULL,customer_name VARCHAR(120) NOT NULL,phone VARCHAR(20) NOT NULL,address VARCHAR(255) NOT NULL DEFAULT '',fulfillment ENUM('pickup','delivery') NOT NULL,payment_method ENUM('cash','bank_transfer') NOT NULL,payment_status ENUM('unpaid','paid','refunded') NOT NULL DEFAULT 'unpaid',status VARCHAR(30) NOT NULL DEFAULT 'pending',subtotal DECIMAL(14,0) NOT NULL,discount DECIMAL(14,0) NOT NULL DEFAULT 0,total DECIMAL(14,0) NOT NULL,promo_code VARCHAR(40) NULL,commission_rate DECIMAL(5,2) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(store_id) REFERENCES stores(id),FOREIGN KEY(staff_id) REFERENCES staff(id));
CREATE TABLE IF NOT EXISTS order_items(id INT PRIMARY KEY AUTO_INCREMENT,order_id INT NOT NULL,product_id INT NOT NULL,name VARCHAR(200) NOT NULL,quantity INT NOT NULL,price DECIMAL(14,0) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS order_history(id INT PRIMARY KEY AUTO_INCREMENT,order_id INT NOT NULL,actor_id INT NOT NULL,status VARCHAR(30) NOT NULL,note VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS service_requests(id INT PRIMARY KEY AUTO_INCREMENT,order_id INT NOT NULL,type ENUM('cancel','return') NOT NULL,reason VARCHAR(255) NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',note VARCHAR(255) NOT NULL DEFAULT '',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY one_request(order_id,type),FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS replenishments(id INT PRIMARY KEY AUTO_INCREMENT,store_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL,note VARCHAR(255) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(store_id) REFERENCES stores(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS inventory_movements(id INT PRIMARY KEY AUTO_INCREMENT,store_id INT NOT NULL,product_id INT NOT NULL,actor_id INT NOT NULL,delta INT NOT NULL,note VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(store_id) REFERENCES stores(id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(actor_id) REFERENCES users(id));
